func:
// Device info and serial number
// 0: Device type
// 1: (skip)
// 2: Communication protocol version
// 3-7: SN byte 01-10 (ASCII, 2 bytes per register)

msg.baseAddr = 0;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 0,
    quantity: 8
};
return msg;

// Firmware versions
// 10: MCU board firmware
// 11-12: (skip)
// 13: Control board firmware
// 14: Communication board firmware

msg.baseAddr = 10;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 10,
    quantity: 5
};
return msg;

// Power and config
// 15: Safety type
// 16: Rated power Low
// 17: Rated power High
// 18: MPPT number and phases
// 19: Rated grid voltage

msg.baseAddr = 15;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 15,
    quantity: 5
};
return msg;

// Grid settings - read separately due to gaps
// First read 51
msg.baseAddr = 51;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 51,
    quantity: 1
};
return msg;

// Battery config - read 204 first
msg.baseAddr = 204;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 204,
    quantity: 1
};
return msg;

// Generator and export config
// Read 235 and 244 together (close)
msg.baseAddr = 235;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 235,
    quantity: 10  // 235-244
};
return msg;

// Grid settings continued
// 285: Grid Frequency
// 286: Grid Type

msg.baseAddr = 285;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 285,
    quantity: 2
};
return msg;

// Battery control mode
msg.baseAddr = 213;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 213,
    quantity: 1
};
return msg;

// Lithium battery type
msg.baseAddr = 325;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 325,
    quantity: 1
};
return msg;

// Generator connected to grid input
msg.baseAddr = 291;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 291,
    quantity: 1
};
return msg;

// Build SystemConnectionStructure from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("SystemConnectionStructure: missing base address");
    return null;
}

// Helper: decode 16-bit register to 2 ASCII chars
function regToAscii(val) {
    const hi = (val >> 8) & 0xFF;
    const lo = val & 0xFF;
    let s = "";
    if (hi >= 32 && hi < 127) s += String.fromCharCode(hi);
    if (lo >= 32 && lo < 127) s += String.fromCharCode(lo);
    return s;
}

// Helper: combine low+high word to 32-bit
function u32(low, high) {
    return ((high || 0) << 16) | (low || 0);
}

// ---- Store partials ----

// Device Info 0-7
if (baseAddr === 0) {
    const deviceType = data[0] || 0;           // 0
    const protocolVer = data[2] || 0;          // 2

    // Serial number from registers 3-7 (5 regs = 10 ASCII chars)
    let sn = "";
    for (let i = 3; i <= 7; i++) {
        sn += regToAscii(data[i] || 0);
    }

    flow.set("scs_part_device_info", {
        deviceType: deviceType,
        deviceTypeHex: "0x" + deviceType.toString(16).padStart(4, '0'),
        protocolVersion: protocolVer,
        serialNumber: sn.trim()
    });
}

// Firmware 10-14
else if (baseAddr === 10) {
    flow.set("scs_part_firmware", {
        mcuBoardRaw: data[0] || 0,             // 10
        controlMainRaw: data[3] || 0,          // 13
        commMainRaw: data[4] || 0              // 14
    });
}

// Power Config 15-19
else if (baseAddr === 15) {
    const safetyType = data[0] || 0;           // 15
    const ratedPowerLow = data[1] || 0;        // 16
    const ratedPowerHigh = data[2] || 0;       // 17
    const mpptPhases = data[3] || 0;           // 18
    const gridVoltageLevel = data[4] || 0;     // 19

    // Rated power in 0.1W, convert to W
    const ratedPowerW = Math.round(u32(ratedPowerLow, ratedPowerHigh) * 0.1);

    // Decode MPPT and phases from register 18
    // Format varies by model - typically: high byte = MPPT count, low byte = phase info
    const mpptCount = (mpptPhases >> 8) & 0xFF;
    const phaseInfo = mpptPhases & 0xFF;

    flow.set("scs_part_power_config", {
        safetyTypeRaw: safetyType,
        ratedPowerW: ratedPowerW,
        mpptAndPhasesRaw: mpptPhases,
        mpptCount: mpptCount || 4,  // Default to 4 if 0
        gridVoltageLevel: gridVoltageLevel
    });
}

// Grid 51
else if (baseAddr === 51) {
    flow.set("scs_part_grid_51", {
        gridStandardRaw: data[0] || 0
    });
}

// Grid 285-286
else if (baseAddr === 285) {
    const gridFreq = data[0] || 0;             // 285: 0=50Hz, 1=60Hz
    const gridType = data[1] || 0;             // 286

    flow.set("scs_part_grid_285", {
        gridFrequencyHz: gridFreq === 0 ? 50 : 60,
        gridVoltageLevelCode: gridType
    });
}

// Battery 204
else if (baseAddr === 204) {
    flow.set("scs_part_battery_204", {
        ratedCapacityAh: data[0] || 0
    });
}

// Battery 213
else if (baseAddr === 213) {
    const mode = data[0];
    let modeStr = "capacity";
    if (mode === 0) modeStr = "voltage";
    else if (mode === 2) modeStr = "no_battery";

    flow.set("scs_part_battery_213", {
        batteryControlMode: modeStr
    });
}

// Battery 325
else if (baseAddr === 325) {
    const bmsType = data[0] || 0;
    const bmsTypes = {
        0: "PYLON_SOLAX_CAN",
        1: "TIANBONDA_RS485",
        2: "PYLON_RS485",
        3: "WS_RS485",
        4: "PYLONLV_CAN",
        5: "UZENERGY_CAN"
    };

    flow.set("scs_part_battery_325", {
        lithiumBatteryTypeRaw: bmsType,
        lithiumBatteryType: bmsTypes[bmsType] || "UNKNOWN_" + bmsType
    });
}

// Generator 235-244
else if (baseAddr === 235) {
    const inputMode = data[0] || 0;            // 235
    const exportLimit = data[9] || 0;          // 244

    const inputModes = {
        0: "gen_input_only",
        1: "smart_load",
        2: "inverter_input"
    };

    flow.set("scs_part_generator", {
        inputMode: inputModes[inputMode] || "unknown",
        inputModeRaw: inputMode,
        exportLimitMode: exportLimit
    });
}

// Generator 291
else if (baseAddr === 291) {
    flow.set("scs_part_gen_291", {
        connectedToGridInput: (data[0] || 0) === 1
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const deviceInfoPart = flow.get("scs_part_device_info");
const firmwarePart = flow.get("scs_part_firmware");
const powerConfigPart = flow.get("scs_part_power_config");
const grid51Part = flow.get("scs_part_grid_51");
const grid285Part = flow.get("scs_part_grid_285");
const battery204Part = flow.get("scs_part_battery_204");
const battery213Part = flow.get("scs_part_battery_213");
const battery325Part = flow.get("scs_part_battery_325");
const generatorPart = flow.get("scs_part_generator");
const gen291Part = flow.get("scs_part_gen_291");

// Need all parts
if (!deviceInfoPart || !firmwarePart || !powerConfigPart || 
    !grid51Part || !grid285Part || 
    !battery204Part || !battery213Part || !battery325Part ||
    !generatorPart || !gen291Part) {
    return null;
}

const deviceId = global.get("DEVICE_ID") || env.get("DEVICE_ID") || "EC100-DEV-001";

// Determine grid type string
const gridTypeMap = {
    0: "single_phase",
    1: "split_phase",
    2: "three_phase",
    3: "single_phase"
};

// Determine export limit mode string
const exportLimitMap = {
    0: "sell_enabled",
    1: "built_in_ct",
    2: "external_meter"
};

const state = {
    kind: "SystemConnectionStructure",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,
    schemaVersion: 1,

    inverter: {
        deviceType: deviceInfoPart.deviceTypeHex,
        inverterModel: null,  // From config/datasheet
        serialNumber: deviceInfoPart.serialNumber,

        firmware: {
            protocolVersion: deviceInfoPart.protocolVersion.toString(),
            mcuBoardRaw: firmwarePart.mcuBoardRaw,
            controlMainRaw: firmwarePart.controlMainRaw,
            commMainRaw: firmwarePart.commMainRaw
        },

        ratedPowerW: powerConfigPart.ratedPowerW,

        acSide: {
            mpptAndPhasesRaw: powerConfigPart.mpptAndPhasesRaw,
            batteryInputCount: 1,  // Default, not in protocol
            outputTopology: null,  // Not in protocol
            gridType: gridTypeMap[grid285Part.gridVoltageLevelCode] || null,
            regionVariant: null,   // Not in protocol
            safetyTypeRaw: powerConfigPart.safetyTypeRaw,
            gridPhaseCount: grid285Part.gridVoltageLevelCode === 2 ? 3 : 1,
            gridStandardRaw: grid51Part.gridStandardRaw,
            gridFrequencyHz: grid285Part.gridFrequencyHz,
            gridVoltageLevelCode: powerConfigPart.gridVoltageLevel,
            gridPhaseSequence: null,
            itSystemNeutralUngrounded: false  // Default
        }
    },

    battery: {
        batteryControlMode: battery213Part.batteryControlMode,

        batteryChannels: [
            {
                channelId: 1,
                ratedCapacityAh: battery204Part.ratedCapacityAh,
                nominalVoltageV: null,  // From datasheet
                batterySn: null,
                batteryPhysicalAddress: null,
                batterySoftwareVersion: null,
                lithiumBatteryType: battery325Part.lithiumBatteryType
            }
        ]
    },

    generator: {
        inputMode: generatorPart.inputMode,
        connectedToGridInput: gen291Part.connectedToGridInput
    },

    pv: {
        mpptCount: powerConfigPart.mpptCount,
        mppt: [
            { pvChannelId: 1, supportsInput: true, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null },
            { pvChannelId: 2, supportsInput: powerConfigPart.mpptCount >= 2, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null },
            { pvChannelId: 3, supportsInput: powerConfigPart.mpptCount >= 3, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null },
            { pvChannelId: 4, supportsInput: powerConfigPart.mpptCount >= 4, stringMaxCurrentA: null, stringMaxVoltageV: null, recommendedVocAtStcV: null }
        ]
    },

    loadAndGrid: {
        homeLoadConnectionPoint: null,  // From commissioning
        exportLimitMode: exportLimitMap[generatorPart.exportLimitMode] || "unknown",
        currentTransformerOnGridSide: generatorPart.exportLimitMode > 0,
        supportsBackupLoad: true,
        supportsZeroExport: true,
        supportsExternalMeter: true
    }
};

// Clear partials
flow.set("scs_part_device_info", null);
flow.set("scs_part_firmware", null);
flow.set("scs_part_power_config", null);
flow.set("scs_part_grid_51", null);
flow.set("scs_part_grid_285", null);
flow.set("scs_part_battery_204", null);
flow.set("scs_part_battery_213", null);
flow.set("scs_part_battery_325", null);
flow.set("scs_part_generator", null);
flow.set("scs_part_gen_291", null);

flow.set("systemConnectionStructureSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;
